package com.testora.ui;
import com.testora.judge.*;import com.testora.model.*;import com.testora.service.*;import com.testora.util.ConsoleUtil;import java.nio.file.*;import java.util.*;
/** Student problem browsing and source-file submission menu. */
public class StudentMenu extends Menu {private final ProblemService problems=new ProblemService();private final SubmissionService submissions;public StudentMenu(Scanner s,User u,JudgeQueue q){super(s,u);submissions=new SubmissionService(q);}public void show(){while(true){ConsoleUtil.line();System.out.println("1 List/search  2 View/solve  3 My submissions  0 Logout");int c=ConsoleUtil.readInt(in,"> ");if(c==0)return;if(c==1)list();else if(c==2)solve();else if(c==3)history();}}
 private void list(){String d=ConsoleUtil.read(in,"Difficulty (or blank): ");String q=ConsoleUtil.read(in,"Title search (or blank): ");problems.browse(d,q).forEach(p->System.out.printf("%d | %s | %s | %s%n",p.getId(),p.getTitle(),p.getDifficulty(),p.getTopicName()));}
 private void solve(){long id=ConsoleUtil.readInt(in,"Problem id: ");var p=problems.find(id);if(p.isEmpty()){System.out.println("Not found.");return;}System.out.println(p.get().getDescription());problems.tests(id,false).forEach(t->System.out.println("Sample input: "+t.input()+" => "+t.expectedOutput()));try{Path f=Path.of(ConsoleUtil.read(in,"Path to .java file: "));if(!f.toString().endsWith(".java")||!Files.isRegularFile(f)){System.out.println("Provide an existing .java file.");return;}JudgeOutcome o=submissions.submit(user.getId(),p.get(),f,problems.tests(id,true));System.out.println("Verdict: "+o.verdict()+", score: "+o.score()+", time: "+o.timeMs()+"ms");o.results().forEach(r->System.out.println("Test "+r.testcaseId()+": "+r.verdict()));if(!o.detail().isBlank())System.out.println(o.detail());}catch(Exception e){System.out.println("Submission failed: "+e.getMessage());}}
 private void history(){try{submissions.history(user.getId()).forEach(x->System.out.println(x.submittedAt()+" problem "+x.problemId()+" "+x.verdict()+" "+x.score()));}catch(Exception e){System.out.println(e.getMessage());}}
}
